def max_open(s):
    res={}
    for f in range(3):
        cur=0; mx=0; mstart=0; start=f
        i=f
        while i+3<=len(s):
            if s[i:i+3] in stop:
                if cur>mx: mx=cur; mstart=start
                cur=0; start=i+3
            else:
                cur+=3
            i+=3
        if cur>mx: mx=cur; mstart=start
        res[f]=(mstart,mstart+mx,mx)
    return res
